var jsonData = pm.response.json();

pm.test("status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test('should return a user ID', function() {
    pm.expect(jsonData).to.have.property('id');
    pm.expect(jsonData.id).to.not.be.empty;
});

pm.test('should not have the same user ID as the first user', function() {
    pm.expect(jsonData).to.have.property('id');
    pm.expect(jsonData.id).to.not.equal(pm.environment.get('userId'));
});

pm.test('should return the correct username', function() {
    pm.expect(jsonData).to.have.property('username');
    pm.expect(jsonData.username).to.equal(pm.environment.get("otherUser"));
});

pm.environment.set("otherUserId", jsonData.id);
